const items = $input.all();

function isNumeric(val) {
  if (typeof val === 'number') return !isNaN(val) && isFinite(val);
  if (typeof val !== 'string') return false;
  const trimmed = val.trim();
  if (trimmed === '') return false;
  const num = Number(trimmed);
  return !isNaN(num) && isFinite(num);
}

function parseNumeric(val) {
  if (typeof val === 'number') return val;
  return Number(String(val).trim());
}

// Default mock experience records for registered prototype bidders
const MOCK_BIDDER_PROJECTS = {
  "ABC Technologies Pvt Ltd": [
    {
      project_id: "PROJ-ABC-001",
      project_name: "State Smart City Core Integration",
      client_name: "Urban Development Department",
      project_value: 1500000,
      completion_date: "2024-06-10",
      similarity: true,
      completion_certificate: true,
      certificate_document_id: "DOC-EXP-001"
    },
    {
      project_id: "PROJ-ABC-002",
      project_name: "Enterprise Portal & Security Layer",
      client_name: "Power Distribution Corporation",
      project_value: 1200000,
      completion_date: "2023-08-15",
      similarity: true,
      completion_certificate: true,
      certificate_document_id: "DOC-EXP-002"
    },
    {
      project_id: "PROJ-ABC-003",
      project_name: "Cloud Migration & Managed DevOps",
      client_name: "Municipal Services Department",
      project_value: 1800000,
      completion_date: "2022-11-20",
      similarity: true,
      completion_certificate: true,
      certificate_document_id: "DOC-EXP-003"
    }
  ]
};

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-EXP-DEMO";
  const tenderId = data.tender_id || "TENDER-EXP-DEMO";
  const bidderId = data.bidder_id || "BIDDER-EXP-DEMO";
  const bidderName = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();

  // 1. Requirements validation
  const rawReqs = data.experience_requirements || {};
  const parsedReqs = {
    minimum_similar_works: 3,
    minimum_project_value: 1000000,
    experience_period_years: 5,
    require_completion_certificate: true,
    similarity_required: true
  };

  if (rawReqs.minimum_similar_works !== undefined && rawReqs.minimum_similar_works !== null) {
    if (!isNumeric(rawReqs.minimum_similar_works)) {
      errors.push(`Invalid requirement: minimum_similar_works must be a number, received '${rawReqs.minimum_similar_works}'`);
    } else {
      const n = parseNumeric(rawReqs.minimum_similar_works);
      if (n < 0) errors.push(`Invalid requirement: minimum_similar_works cannot be negative (${n})`);
      else parsedReqs.minimum_similar_works = n;
    }
  }

  if (rawReqs.minimum_project_value !== undefined && rawReqs.minimum_project_value !== null) {
    if (!isNumeric(rawReqs.minimum_project_value)) {
      errors.push(`Invalid requirement: minimum_project_value must be a number, received '${rawReqs.minimum_project_value}'`);
    } else {
      const n = parseNumeric(rawReqs.minimum_project_value);
      if (n < 0) errors.push(`Invalid requirement: minimum_project_value cannot be negative (${n})`);
      else parsedReqs.minimum_project_value = n;
    }
  }

  if (rawReqs.experience_period_years !== undefined && rawReqs.experience_period_years !== null) {
    if (!isNumeric(rawReqs.experience_period_years)) {
      errors.push(`Invalid requirement: experience_period_years must be a number, received '${rawReqs.experience_period_years}'`);
    } else {
      const n = parseNumeric(rawReqs.experience_period_years);
      if (n <= 0) errors.push(`Invalid requirement: experience_period_years must be positive (${n})`);
      else parsedReqs.experience_period_years = n;
    }
  }

  if (rawReqs.require_completion_certificate !== undefined) {
    parsedReqs.require_completion_certificate = Boolean(rawReqs.require_completion_certificate);
  }
  if (rawReqs.similarity_required !== undefined) {
    parsedReqs.similarity_required = Boolean(rawReqs.similarity_required);
  }

  // 2. Evidence extraction
  const rawEvidence = data.experience_evidence || null;
  let projects = null;
  let rawProvided = false;

  if (rawEvidence && typeof rawEvidence === 'object') {
    rawProvided = true;
    if (rawEvidence.projects !== undefined && rawEvidence.projects !== null) {
      if (!Array.isArray(rawEvidence.projects)) {
        errors.push("Invalid experience_evidence: 'projects' must be an array");
      } else {
        projects = rawEvidence.projects;
      }
    } else {
      projects = [];
    }
  } else if (data.projects && Array.isArray(data.projects)) {
    rawProvided = true;
    projects = data.projects;
  }

  // Fallback to mock projects if none provided
  if (!rawProvided || projects === null) {
    projects = MOCK_BIDDER_PROJECTS[bidderName] || [];
  }

  // 3. Project item validation
  const validatedProjects = [];
  if (Array.isArray(projects)) {
    projects.forEach((p, idx) => {
      const pId = p.project_id || `PROJ-${idx + 1}`;

      // Value validation
      if (p.project_value !== undefined && p.project_value !== null) {
        if (!isNumeric(p.project_value)) {
          errors.push(`Invalid project data: project '${pId}' value contains non-numeric value '${p.project_value}'`);
        } else {
          const numVal = parseNumeric(p.project_value);
          if (numVal < 0) {
            errors.push(`Invalid project data: project '${pId}' value cannot be negative (${numVal})`);
          }
        }
      } else {
        errors.push(`Invalid project data: project '${pId}' missing required 'project_value'`);
      }

      // Date validation
      if (p.completion_date) {
        const parsedDate = new Date(p.completion_date);
        if (isNaN(parsedDate.getTime())) {
          errors.push(`Invalid project data: project '${pId}' contains invalid completion_date '${p.completion_date}'`);
        }
      } else {
        errors.push(`Invalid project data: project '${pId}' missing required 'completion_date'`);
      }

      validatedProjects.push({
        ...p,
        project_id: pId,
        project_value: isNumeric(p.project_value) ? parseNumeric(p.project_value) : p.project_value
      });
    });
  }

  // Evaluation reference date (supports request-level metadata or execution date)
  const evalDateStr = data.metadata?.evaluation_date || data.evaluation_date || new Date().toISOString();
  const evalDate = new Date(evalDateStr);
  const validEvalDate = !isNaN(evalDate.getTime()) ? evalDate : new Date();

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      experience_requirements: parsedReqs,
      projects: validatedProjects,
      evidence_provided: rawProvided,
      evaluation_date: validEvalDate.toISOString(),
      valid_schema: errors.length === 0,
      validation_errors: errors,
      raw_input: data
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) {
    return { json: { ...data, evaluation_result: null } };
  }

  const reqs = data.experience_requirements;
  const projects = data.projects || [];
  const evalDate = new Date(data.evaluation_date);

  // Calculate cutoff timestamp: evaluation_date minus experience_period_years
  const periodYears = reqs.experience_period_years || 5;
  const cutoffDate = new Date(evalDate.getTime());
  cutoffDate.setFullYear(cutoffDate.getFullYear() - periodYears);

  const checks = [];
  const issues = [];
  const qualifyingProjects = [];
  const rejectedProjects = [];

  const seenProjectIds = new Set();
  let certificatesCount = 0;
  let similarityCount = 0;

  // Evaluate each submitted project against tender eligibility criteria
  projects.forEach(p => {
    const pId = p.project_id;
    const rejections = [];

    // 1. Duplicate detection
    if (seenProjectIds.has(pId)) {
      rejections.push("Duplicate project ID detected");
    } else {
      seenProjectIds.add(pId);
    }

    // 2. Similarity check
    const isSimilar = p.similarity === true || p.is_similar === true;
    if (isSimilar) similarityCount++;
    if (reqs.similarity_required && !isSimilar) {
      rejections.push("Project does not meet technical similarity criteria");
    }

    // 3. Experience period check
    const compDate = new Date(p.completion_date);
    const inPeriod = !isNaN(compDate.getTime()) && compDate >= cutoffDate && compDate <= evalDate;
    if (!inPeriod) {
      rejections.push(`Completion date (${p.completion_date}) is outside the required ${periodYears}-year period (cutoff: ${cutoffDate.toISOString().split('T')[0]})`);
    }

    // 4. Project value threshold check
    const pVal = typeof p.project_value === 'number' ? p.project_value : 0;
    const valuePass = pVal >= reqs.minimum_project_value;
    if (!valuePass) {
      rejections.push(`Project value ₹${pVal.toLocaleString('en-IN')} is below required minimum ₹${reqs.minimum_project_value.toLocaleString('en-IN')}`);
    }

    // 5. Completion certificate check
    const hasCert = p.completion_certificate === true || p.has_certificate === true;
    if (hasCert) certificatesCount++;
    if (reqs.require_completion_certificate && !hasCert) {
      rejections.push("Mandatory completion certificate is missing");
    }

    if (rejections.length === 0) {
      qualifyingProjects.push(p);
      checks.push({
        rule: "PROJECT_ELIGIBILITY",
        project_id: pId,
        project_value: pVal,
        completion_date: p.completion_date,
        result: "PASS"
      });
    } else {
      rejectedProjects.push({
        project_id: pId,
        reasons: rejections
      });
      issues.push(`Project ${pId}: ${rejections.join('; ')}`);
      checks.push({
        rule: "PROJECT_ELIGIBILITY",
        project_id: pId,
        project_value: pVal,
        completion_date: p.completion_date,
        rejection_reasons: rejections,
        result: "FAIL"
      });
    }
  });

  // Rule: MINIMUM_SIMILAR_WORKS count
  const countPass = qualifyingProjects.length >= reqs.minimum_similar_works;
  checks.push({
    rule: "MINIMUM_SIMILAR_WORKS",
    required: reqs.minimum_similar_works,
    actual: qualifyingProjects.length,
    result: countPass ? "PASS" : "FAIL"
  });

  if (!countPass) {
    issues.push(`Qualifying projects count (${qualifyingProjects.length}) is below required minimum (${reqs.minimum_similar_works})`);
  }

  if (projects.length === 0) {
    issues.push("Required project experience evidence is missing");
  }

  return {
    json: {
      ...data,
      evaluation_result: {
        projects_evaluated: projects.length,
        qualifying_projects: qualifyingProjects.length,
        minimum_required_projects: reqs.minimum_similar_works,
        minimum_project_value: reqs.minimum_project_value,
        experience_period_years: periodYears,
        qualifying_project_list: qualifyingProjects.map(p => p.project_id),
        rejected_projects: rejectedProjects,
        certificates_verified: certificatesCount,
        similarity_verified: similarityCount,
        compliance_checks: checks,
        evaluation_issues: issues,
        count_passed: countPass
      }
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";
  const allIssues = [];

  if (!data.valid_schema) {
    status = "ERROR";
    confidence = 0.0;
    riskLevel = "HIGH";
    allIssues.push(...(data.validation_errors || ["Invalid experience input data encountered"]));
  } else {
    const evalRes = data.evaluation_result || {};
    const issues = evalRes.evaluation_issues || [];
    allIssues.push(...issues);

    if (evalRes.projects_evaluated === 0) {
      status = "NOT_VERIFIED";
      confidence = 0.95;
      riskLevel = "HIGH";
    } else if (!evalRes.count_passed || evalRes.rejected_projects.length > 0 || issues.length > 0) {
      status = "NOT_VERIFIED";
      confidence = 0.98;
      riskLevel = "HIGH";
    } else {
      status = "VERIFIED";
      confidence = 0.99;
      riskLevel = "LOW";
    }
  }

  const evalRes = data.evaluation_result || {};
  const reqs = data.experience_requirements || {};

  return {
    json: {
      agent: "EXPERIENCE_AGENT",
      status,
      confidence,
      evidence: {
        projects_evaluated: evalRes.projects_evaluated || 0,
        qualifying_projects: evalRes.qualifying_projects || 0,
        minimum_required_projects: reqs.minimum_similar_works || 0,
        minimum_project_value: reqs.minimum_project_value || 0,
        experience_period_years: reqs.experience_period_years || 0,
        checks: evalRes.compliance_checks || [],
        rejected_projects: evalRes.rejected_projects || [],
        certificates_verified: evalRes.certificates_verified || 0,
        similarity_verified: evalRes.similarity_verified || 0,
        registry_source: data.evidence_provided ? "BIDDER_SUBMISSION" : "MOCK_PORTAL_REGISTRY"
      },
      issues: allIssues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "EXPERIENCE_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Experience verification agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Experience verification agent failed unexpectedly"],
    risk_level: "HIGH",
    timestamp: new Date().toISOString()
  }
}));
